const REFERENCE_SOURCES_GENERAL = [
  { label: 'NCF 2005 (National Curriculum Framework)', url: 'https://ncert.nic.in/pdf/nc-framework/nf2005-english.pdf' },
  { label: 'NCF 2023 (School Education)', url: 'https://ncert.nic.in/pdf/NCF-2023-Enlish.pdf' },
  { label: 'NEP 2020', url: 'https://www.education.gov.in/sites/upload_files/mhrd/files/NEP_Final_English_0.pdf' },
  { label: 'RTE Act 2009', url: 'https://www.indiacode.nic.in/handle/123456789/1359' },
];

const REFERENCE_SOURCES_BY_SUBJECT = {
  'CDP': [
    { label: 'Piaget (Wikipedia)', url: 'https://en.wikipedia.org/wiki/Jean_Piaget' },
    { label: 'Vygotsky (Wikipedia)', url: 'https://en.wikipedia.org/wiki/Lev_Vygotsky' },
    { label: 'Kohlberg (Wikipedia)', url: 'https://en.wikipedia.org/wiki/Lawrence_Kohlberg' },
  ],
  'Geography': [ { label: 'NCERT Geography textbooks (eBooks portal)', url: 'https://ncert.nic.in/textbook.php' } ],
  'History': [ { label: 'NCERT History textbooks', url: 'https://ncert.nic.in/textbook.php' } ],
  'Science': [ { label: 'NCERT Science textbooks', url: 'https://ncert.nic.in/textbook.php' } ],
  'Maths': [ { label: 'NCERT Maths textbooks', url: 'https://ncert.nic.in/textbook.php' } ],
  'EVS': [ { label: 'NCERT EVS textbooks', url: 'https://ncert.nic.in/textbook.php' } ],
  'Hindi': [ { label: 'NCERT Hindi textbooks', url: 'https://ncert.nic.in/textbook.php' } ],
  'English': [ { label: 'CBSE Academic (curriculum/syllabus)', url: 'https://cbseacademic.nic.in/' } ],
};

function getReferenceSources(subject){
  return [...REFERENCE_SOURCES_GENERAL, ...(REFERENCE_SOURCES_BY_SUBJECT[subject] || [])];
}

function getTeachingLevel(examTypeRaw){
  const s = String(examTypeRaw||'').toLowerCase();
  const hasAny = (...words) => words.some(w => s.includes(w));
  if (hasAny('class 1-5','class 1–5','classes 1-5','class i-v','primary teacher','primary (class','prt')) return 'Primary (Class 1–5)';
  if (hasAny('class 6-8','class 6–8','class 9-10','class 6-10','upper primary','tgt')) return 'Upper Primary/Secondary (Class 6–10)';
  if (hasAny('class 11','class 12','senior secondary','pgt')) return 'Senior Secondary (Class 11–12)';
  if (hasAny('paper i','paper 1') && !hasAny('paper ii','paper 2')) return 'Primary (Class 1–5)';
  if (hasAny('paper ii','paper 2')) return 'Upper Primary/Secondary (Class 6–10)';
  return 'Not explicitly stated in EXAM TYPE — infer the most likely level from TOPIC/SUBJECT/EXAM TYPE context and state your inference once in Publisher Notes';
}

function buildReferenceSourcesBlock(subject, extraSourceUrls){
  const sources = getReferenceSources(subject);
  const extra = (extraSourceUrls || '')
    .split('\n').map(s=>s.trim()).filter(Boolean);
  const lines = sources.map(s => `- ${s.label}: ${s.url}`);
  extra.forEach(u => lines.push(`- (manually added): ${u}`));
  if(!lines.length) return '';
  return `## REFERENCE SOURCES FOR THIS RUN
Use these as supporting material where genuinely relevant to TOPIC — same whitelist rules as HARD BAN 6 still apply for any URL you cite. Use only the parts that are actually relevant to this specific topic, not all of them. Never copy source text verbatim — synthesize into your own teacher-voice prose. Never invent a claim beyond what these (or your own verified knowledge) actually support.
${lines.join('\n')}`;
}

const NCERT_KB_SUBJECT_MAP = {
  'Geography': ['Geography'],
  'History': ['History'],
  'Science': ['Science', 'Biology', 'Chemistry'],
  'EVS': ['Science', 'Geography'],
  'Maths': ['Maths'],
  'Hindi': ['Hindi'],
};

function buildNcertKnowledgeBaseBlock(subject){
  const folders = NCERT_KB_SUBJECT_MAP[subject];
  if(!folders || !folders.length) return '';
  const base = 'https://github.com/bugignore/question-factory/tree/main/Automation/ncert-knowledge-base/by-subject';
  const links = folders.map(f => `- ${f}: ${base}/${encodeURIComponent(f)}`).join('\n');
  return `

## NCERT KNOWLEDGE BASE (check this FIRST, before any general web search)
This repo maintains its own cleaned NCERT chapter-text corpus for SUBJECT — this is the
preferred grounding source for this run, ahead of an open-ended web search. If you have the
ability to open a URL, browse these folders and read whichever chapter .txt files are actually
relevant to TOPIC before writing — treat the chapter text as evidence to extract facts from and
explain in your own words (same RAG/SOURCES rule as above: never copy source prose verbatim).
If a claim traces back to something you read here, cite the ORIGINAL NCERT source
(ncert.nic.in — see REFERENCE SOURCES above) in the article's References, not this GitHub
mirror. If you have no browsing ability, skip this section entirely and rely on your own
verified knowledge under the same honesty rules — never substitute a generic, uncurated web
search for this repo's own knowledge base.
${links}`;
}

function outputContract(){
  return `

=== PIPELINE OUTPUT CONTRACT (read this after finishing everything above — mandatory, additive only) ===
Everything specified above still applies in full — every rule, every section, every format, every word-count target. This contract only adds wrapper markers around your final answer so an automated script can extract the pieces; it changes nothing about what you write, only how it is packaged at the very end.

Output exactly three blocks, in this order, with nothing outside them (no extra commentary before, between, or after).

CRITICAL RENDERING RULE: the content of EVERY block (including the HTML body and the plain-text publisher notes) MUST sit inside a fenced code block (three backticks on their own line before and after the content, immediately inside the sentinel markers). This is because chat interfaces render raw HTML visually — without the code fence, the person copying your reply gets rendered text with every tag destroyed. The fence is what keeps your output copyable as source. Never skip it.

ADDITIVE FIELDS — two extra fields in SEO_JSON beyond what's specified above:
- "imageAltText": ONE single ALT text string for the article's featured/OG image, derived from whichever of your visuals best represents the topic as a whole — contains the Focus Keyphrase or a close variant, plus a concrete description of what the image shows.
- "imagePrompt": a complete, ready-to-paste AI image-generation prompt (for Midjourney/DALL·E/Stable Diffusion) for that same featured image. Style it as a **loud, high-CTR YouTube-thumbnail-style graphic, never clean/minimal/corporate**: exaggerated facial expression (shock/confusion/excitement) on a student or teacher character, bold saturated colors, high contrast, a big punchy focal object tied to the topic, dramatic lighting/glow, thick outlines — the kind of image built to stop a scroll. Describe subject, composition, and this exaggerated attention-grabbing style explicitly — 16:9 aspect ratio suitable for a WordPress featured image, and explicitly specify NO readable text/typography baked into the image (WordPress overlays the title separately).

<<<SEO_JSON>>>
\`\`\`json
{
  "focusKeyword": "...",
  "seoTitle": "...",
  "slug": "...",
  "metaDescription": "...",
  "h1": "...",
  "imageAltText": "...",
  "imagePrompt": "..."
}
\`\`\`
<<<END_SEO_JSON>>>

<<<NOTES_BODY_HTML>>>
\`\`\`html
(the complete pure-HTML notes body exactly as specified above — the Table of Contents through the end of Section 9 and its ad slot, nothing removed, nothing summarized)
\`\`\`
<<<END_NOTES_BODY_HTML>>>

<<<PUBLISHER_NOTES>>>
\`\`\`
(the publisher-facing notes exactly as specified above — sources to verify, softened/omitted claims, PYQ label counts, visuals list, variation picks used — plain text)
\`\`\`
<<<END_PUBLISHER_NOTES>>>

If you run out of space and cannot finish, stop cleanly at the end of a complete HTML element — the user will send "continue" and you must resume EXACTLY where you stopped (same block, inside a new code fence, no repetition of anything already written, no fresh introduction).
`;
}

export function buildNotesPrompt({ topic, examType, subject, hindiPercent, year, masterPromptText, extraSourceUrls }) {
  let master = masterPromptText
    .replace('{{REFERENCE_SOURCES_BLOCK}}', buildReferenceSourcesBlock(subject, extraSourceUrls) + buildNcertKnowledgeBaseBlock(subject))
    .replaceAll('{{TEACHING_LEVEL}}', getTeachingLevel(examType));

  const config = `=== RUN THIS GENERATION WITH THESE EXACT INPUT VARIABLES ===
TOPIC: ${topic}
EXAM TYPE: ${examType}
SUBJECT: ${subject}
TARGET_YEAR: ${year} (this is the locked constant already specified inside the prompt below — do not change it)
LANGUAGE MIX: Hindi ${hindiPercent}% + English ${100 - hindiPercent}% — this OVERRIDES any Hindi/English language-mix default stated elsewhere in the master prompt below. Apply this ratio to the explanations/tricks/teacher-talk/connecting prose only — key terms, definitions, and technical labels still stay in English regardless of this split.
=== END RUN CONFIGURATION — THE FULL MASTER PROMPT FOLLOWS BELOW, UNCHANGED ===

`;
  return config + master + outputContract();
}
